      <div class="Footer__LeftContainer">
        <div class="Footer__Logo"><img :src="this.logo" /></div>
        <slot />
      </div>
      <div class="Footer__RightContainer">
        <span>{{ copyright }}</span>
      </div>
    </div>
  </div>
</template>
